          title: 'API Post',
          author: 'Jane',
          content: 'Content',
          category: 'News',
          tags: '',
          slug: 'api-post'
        }));
      }
      if (event === 'end') {
        handler();
      }
    }
  };

  let responseBody = '';
  const res = {
    setHeader: () => {},
    writeHead: () => {},
    end: (body) => {
      const data = JSON.parse(body);
      if (!data.id) throw new Error('Response missing ID');
      if (data.title !== 'API Post') throw new Error('Title mismatch');
    }
  };

  api.handle(req, res);
