  let statusCode;
  let responseBody = '';
  const res = {
    setHeader: () => {},
    writeHead: (code) => { statusCode = code; },
    end: (body) => {
      const data = JSON.parse(body);
      if (data.id !== created.id) throw new Error('ID mismatch');
      if (data.title !== 'Read Test') throw new Error('Title mismatch');
    }
  };

  api.handle(req, res);
  if (statusCode !== 200) throw new Error(`Expected 200, got ${statusCode}`);
});

test('API list posts', () => {
  const db = new BlogDatabase('/tmp/test-api-3.json');
  for (let i = 0; i < 3; i++) {
    db.create({ title: `Post ${i}`, author: 'Jane', content: 'X', category: 'News', tags: '', slug: `p${i}` });
  }

  const api = new BlogAPI(db);
  const req = { url: '/api/blogs?page=1&limit=10', method: 'GET' };

  const res = {
    setHeader: () => {},
    writeHead: () => {},
