// ============================================================================

console.log('\n⚠️  Deployment Problem Scenarios\n');

test('Database concurrency: Multiple operations', () => {
  const db = new BlogDatabase('/tmp/test-concurrency.json');

  // Simulate rapid operations
  const ids = [];
  for (let i = 0; i < 10; i++) {
    const post = db.create({
      title: `Concurrent ${i}`,
      author: 'Jane',
      content: 'X',
      category: 'News',
      tags: '',
      slug: `conc-${i}`
    });
    ids.push(post.id);
  }

  // Verify all created
  if (db.posts.size !== 10) throw new Error('Some posts lost during concurrent creation');

  // Verify each can be updated
  ids.forEach(id => {
    db.update(id, { viewCount: 5 });
  });

  ids.forEach(id => {
    const post = db.getById(id);
    if (post.viewCount !== 5) throw new Error('Update failed');
  });
});

test('Database file corruption recovery', () => {
  const dbPath = '/tmp/test-corruption.json';

  // Create valid DB
  const db1 = new BlogDatabase(dbPath);
  db1.create({ title: 'Original', author: 'Jane', content: 'X', category: 'News', tags: '', slug: 'orig' });

  // Corrupt file
  fs.writeFileSync(dbPath, 'INVALID JSON {{{');

  // Attempt recovery
  const db2 = new BlogDatabase(dbPath);
  if (db2.posts.size !== 0) {
    // Recovery worked - started fresh
  }

  fs.unlinkSync(dbPath);
});

test('Memory limits: Large post creation', () => {
  const db = new BlogDatabase('/tmp/test-memory.json');

  // Create large content
  const largeContent = 'X'.repeat(100000);
  const post = db.create({
    title: 'Large Post',
    author: 'Jane',
    content: largeContent,
    category: 'News',
    tags: '',
    slug: 'large'
  });

  if (!post.id) throw new Error('Large post creation failed');
  if (post.content.length !== 100000) throw new Error('Content truncated');
});

test('CORS headers present', () => {
  const db = new BlogDatabase('/tmp/test-cors.json');
  const api = new BlogAPI(db);

  let corsHeaders = {};
  const req = { url: '/api/blogs', method: 'OPTIONS' };
  const res = {
    setHeader: (key, value) => {
      corsHeaders[key] = value;
    },
    writeHead: () => {},
    end: () => {}
  };

  api.handle(req, res);

  if (!corsHeaders['Access-Control-Allow-Origin']) throw new Error('Missing CORS Allow-Origin');
  if (!corsHeaders['Access-Control-Allow-Methods']) throw new Error('Missing CORS Allow-Methods');
});

test('Input validation: SQL injection attempt', () => {
  const db = new BlogDatabase('/tmp/test-injection.json');
  const api = new BlogAPI(db);

  const maliciousData = {
    title: "'; DROP TABLE posts; --",
    author: 'Jane',
    content: 'X',
    category: 'News',
    tags: '',
    slug: 'injection'
  };

  const post = db.create(maliciousData);

  // Verify data stored as-is (no SQL execution)
  if (post.title !== "'; DROP TABLE posts; --") throw new Error('Data not stored correctly');
  if (db.posts.size !== 1) throw new Error('Table not compromised (good!)');
});

test('Rate limiting check: Too many requests', () => {
  const db = new BlogDatabase('/tmp/test-rate.json');
  const api = new BlogAPI(db);

  // Note: Current implementation doesn't have rate limiting
  // This test documents the missing feature
  let requestCount = 0;
  for (let i = 0; i < 100; i++) {
    const req = { url: '/api/blogs', method: 'GET' };
    const res = {
      setHeader: () => {},
      writeHead: () => {},
      end: () => { requestCount++; }
    };
    api.handle(req, res);
  }

  if (requestCount !== 100) throw new Error('All requests processed (no rate limiting)');
  // In production, should have: 429 Too Many Requests after threshold
});

// ============================================================================
// SUMMARY
// ============================================================================

console.log('\n' + '='.repeat(60));
console.log(`✅ Passed: ${testsPassed}`);
console.log(`❌ Failed: ${testsFailed}`);
console.log(`📊 Total:  ${testsPassed + testsFailed}`);
console.log('='.repeat(60));

if (testsFailed === 0) {
  console.log('\n🎉 All tests passed!\n');
} else {
  console.log(`\n⚠️  ${testsFailed} test(s) failed\n`);
  process.exit(1);
}

// Cleanup test files
const testFiles = fs.readdirSync('/tmp').filter(f => f.startsWith('test-'));
testFiles.forEach(f => {
  try {
    fs.unlinkSync(path.join('/tmp', f));
  } catch (err) {}
});

