#   "id": 1,
#   "title": "Getting Started with FreeLang",
#   "createdAt": 1710345600000,
#   "updatedAt": 1710345600000,
#   "viewCount": 0,
#   "likes": 0,
#   ...
# }

# List posts (with pagination)
curl http://localhost:3000/api/blogs?page=1&limit=10

# Get specific post
curl http://localhost:3000/api/blogs/1

# Increment view count
curl -X POST http://localhost:3000/api/blogs/1/view

# Add like
