  -H "Content-Type: application/json" \
  -d '{"status": "published", "isDraft": false}'

# Delete post
curl -X DELETE http://localhost:3000/api/blogs/1
```

---

## 🔧 Deployment Problem Solutions

### Problem 1: Database Persistence

**Issue**: JSON file can become corrupted, lost on server crash.

**Solution Implemented**:
```javascript
// Atomic writes
fs.writeFileSync(dataPath, JSON.stringify(data, null, 2));

// Corruption recovery
try {
  const data = JSON.parse(fs.readFileSync(this.dataPath));
  // ... restore
} catch (err) {
  console.warn('Recovery: Starting fresh');
  // Fall back to empty state
}
```

**Production**: Migrate to PostgreSQL
```sql
CREATE TABLE blogs (
  id SERIAL PRIMARY KEY,
  title VARCHAR(255) NOT NULL,
  description TEXT,
  content TEXT NOT NULL,
  author VARCHAR(100),
  category VARCHAR(50),
  tags VARCHAR(500),
  slug VARCHAR(255) UNIQUE,
  featured BOOLEAN DEFAULT false,
  status VARCHAR(20) DEFAULT 'draft',
  isDraft BOOLEAN DEFAULT true,
  viewCount INTEGER DEFAULT 0,
  likes INTEGER DEFAULT 0,
  createdAt BIGINT DEFAULT CURRENT_TIMESTAMP,
  updatedAt BIGINT DEFAULT CURRENT_TIMESTAMP,
  publishedAt BIGINT
);

CREATE INDEX idx_category ON blogs(category);
CREATE INDEX idx_status ON blogs(status);
CREATE INDEX idx_author ON blogs(author);
CREATE UNIQUE INDEX idx_slug ON blogs(slug);
```

---

### Problem 2: Concurrency & Race Conditions

**Issue**: Multiple requests writing simultaneously.

**Solution Implemented**:
```javascript
// All operations save immediately
create(post) {
  // ... add to map
  this.save(); // Atomic file write
}

update(id, updates) {
  // ... modify
  this.save(); // Atomic file write
}
```

**Production**: Use transactions
```javascript
// PostgreSQL with transactions
async function updatePostWithFeedback(id, updates) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query('UPDATE blogs SET ... WHERE id = $1', [id]);
    await client.query('INSERT INTO blog_feedback ... VALUES (...)');
    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}
```

---

### Problem 3: Input Validation & SQL Injection

**Issue**: Malicious input could compromise data.

**Solution Implemented**:
```javascript
// Store malicious strings as-is (no SQL execution in JSON mode)
const post = db.create({
  title: "'; DROP TABLE posts; --"
  // → Stored safely as regular string
});
```

**Production**: Parameterized queries
```javascript
// ❌ NEVER do this:
query = `UPDATE blogs SET title = '${title}' WHERE id = ${id}`;

// ✅ DO this:
query = 'UPDATE blogs SET title = $1 WHERE id = $2';
pool.query(query, [title, id]);
```

---

### Problem 4: CORS & Security Headers

**Issue**: Frontend can't access API from different domain.

**Solution Implemented**:
```javascript
res.setHeader('Access-Control-Allow-Origin', '*');
res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
```

**Production**: Whitelist domains
```javascript
const ALLOWED_ORIGINS = ['https://blog.example.com', 'https://admin.example.com'];

const corsMiddleware = (req, res, next) => {
  const origin = req.headers.origin;
  if (ALLOWED_ORIGINS.includes(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
  }
  next();
};
```

---

### Problem 5: Authentication & Authorization

**Issue**: Anyone can create, edit, delete posts.

**Solution Required**:
```javascript
// JWT Token validation middleware
function verifyToken(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });

  jwt.verify(token, SECRET_KEY, (err, decoded) => {
    if (err) return res.status(403).json({ error: 'Forbidden' });
    req.user = decoded;
    next();
  });
}

// Apply to protected routes
router.post('/api/blogs', verifyToken, handleCreate);
router.put('/api/blogs/:id', verifyToken, handleUpdate);
router.delete('/api/blogs/:id', verifyToken, handleDelete);
```

**Add to server.js**:
```javascript
const jwt = require('jsonwebtoken');
const SECRET_KEY = process.env.JWT_SECRET || 'dev-secret-key';

class BlogAPI {
  handleCreate(req, res) {
    if (!req.user || !req.user.role.includes('admin')) {
      res.writeHead(403);
      res.end(JSON.stringify({ error: 'Not authorized' }));
      return;
    }
    // ... proceed with creation
  }
}
```

---

### Problem 6: Rate Limiting

**Issue**: Same user can spam requests.

**Solution Required**:
```javascript
class RateLimiter {
  constructor(maxRequests = 100, windowMs = 60000) {
    this.requests = new Map();
    this.maxRequests = maxRequests;
    this.windowMs = windowMs;
  }

  isAllowed(ip) {
    const now = Date.now();
    if (!this.requests.has(ip)) {
      this.requests.set(ip, [now]);
      return true;
    }

    const times = this.requests.get(ip)
      .filter(t => now - t < this.windowMs);

    if (times.length >= this.maxRequests) {
      return false;
    }

    times.push(now);
    this.requests.set(ip, times);
    return true;
  }
}

// Usage in API handler
const limiter = new RateLimiter(100, 60000); // 100 req/min

handle(req, res) {
  const ip = req.connection.remoteAddress;
  if (!limiter.isAllowed(ip)) {
    res.writeHead(429);
    res.end(JSON.stringify({ error: 'Too many requests' }));
    return;
  }
  // ... proceed
}
```

---

### Problem 7: Caching

**Issue**: Repeated reads hit database.

**Solution Required**:
```javascript
class CacheLayer {
  constructor(ttl = 60000) {
    this.cache = new Map();
    this.ttl = ttl;
  }

  get(key) {
    const entry = this.cache.get(key);
    if (!entry) return null;

    if (Date.now() - entry.time > this.ttl) {
      this.cache.delete(key);
      return null;
    }

    return entry.value;
  }

  set(key, value) {
    this.cache.set(key, { value, time: Date.now() });
  }

  invalidate(pattern) {
    for (const key of this.cache.keys()) {
      if (key.match(pattern)) {
        this.cache.delete(key);
      }
    }
  }
}

// Usage
const cache = new CacheLayer(5 * 60 * 1000); // 5 min TTL

getById(id) {
  const cacheKey = `post:${id}`;
  let post = cache.get(cacheKey);

  if (!post) {
    post = db.getById(id);
    cache.set(cacheKey, post);
  }

  return post;
}

// Invalidate when updated
update(id, updates) {
  const post = db.update(id, updates);
  cache.invalidate(`^post:`);
  return post;
}
```

---

### Problem 8: Error Handling & Logging

**Issue**: Errors silently fail or expose internals.

**Solution Required**:
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

// Usage
try {
  const post = db.create(data);
  logger.info(`Post created: ${post.id}`);
  res.writeHead(201);
  res.end(JSON.stringify(post));
} catch (err) {
  logger.error(`Create failed: ${err.message}`, { stack: err.stack });
  res.writeHead(500);
  res.end(JSON.stringify({ error: 'Internal server error' }));
}
```

---

### Problem 9: Graceful Shutdown & Health Checks

**Issue**: Server stops abruptly, data lost.

**Solution Implemented**:
```javascript
process.on('SIGINT', () => {
  console.log('\n📦 Saving database...');
  db.save();
  server.close(() => {
    console.log('✅ Server stopped');
    process.exit(0);
  });
});
```

**Production**: Add health check endpoint
```javascript
// GET /health
if (pathname === '/health') {
  const health = {
    status: 'ok',
    uptime: process.uptime(),
    memory: process.memoryUsage(),
    timestamp: new Date().toISOString()
  };
  res.writeHead(200);
  res.end(JSON.stringify(health));
  return;
}
```

